// src/pages/public/Home.jsx
import React, { useCallback, useEffect, useRef, useState } from "react";
import "./Home.css";
import { Link } from "react-router-dom";
import api from "../../api";
import ImgHead from "../../assets/bishopimage.png";
import DefaultThumb from "../../assets/BishopRobertsonTVLogo.png";
import HomeBanner from "../../assets/brtv-home-banner.png";

const CHANNEL_ID = "gworrdns";

/* ─── Utilities ─────────────────────────────────────────── */
const absUrl = (u) => {
  if (!u) return null;
  if (/^https?:\/\//i.test(u)) return u;
  const base = (api?.defaults?.baseURL || "").replace(/\/api\/?$/i, "");
  return u.startsWith("/") ? `${base}${u}` : `${base}/${u}`;
};

async function safeGet(path, opts = {}) {
  try {
    const res = await api.get(path, { ...opts, validateStatus: () => true });
    const status = res?.status ?? 0;
    return { ok: status >= 200 && status < 300, data: res?.data };
  } catch {
    return { ok: false, data: null };
  }
}

function normalizeItems(data) {
  if (!data) return [];
  if (Array.isArray(data)) return data;
  if (Array.isArray(data.items)) return data.items;
  if (Array.isArray(data.videos)) return data.videos;
  if (Array.isArray(data.rows)) return data.rows;
  return [];
}

function parseNextLiveToLocalDate(ts) {
  if (!ts) return null;
  const d = new Date(ts);
  return Number.isNaN(d.getTime()) ? null : d;
}

function formatDuration(totalSec) {
  const s = Math.max(0, Math.floor(totalSec));
  const pad = (n) => String(n).padStart(2, "0");
  return `${pad(Math.floor(s / 86400))}:${pad(Math.floor((s % 86400) / 3600))}:${pad(Math.floor((s % 3600) / 60))}:${pad(s % 60)}`;
}

/* ─── Spinner ────────────────────────────────────────────── */
let _styleInjected = false;
function ensureStyles() {
  if (_styleInjected) return;
  _styleInjected = true;
  const el = document.createElement("style");
  el.textContent = `
    @keyframes brtv-spin { to { transform: rotate(360deg); } }
    @keyframes brtv-dash {
      0%   { stroke-dasharray: 1,200; stroke-dashoffset: 0; }
      50%  { stroke-dasharray: 90,200; stroke-dashoffset: -35; }
      100% { stroke-dasharray: 90,200; stroke-dashoffset: -125; }
    }
    @keyframes live-pulse {
      0%, 100% { opacity: 1; transform: scale(1); }
      50%       { opacity: 0.5; transform: scale(0.85); }
    }
  `;
  document.head.appendChild(el);
}

function CircularSpinner({ size = 40, label = "Loading…" }) {
  useEffect(() => {
    ensureStyles();
  }, []);
  const ring = Math.max(4, Math.round(size / 10));
  return (
    <div className="spinner-wrap">
      <div role="status" aria-label={label}>
        <svg
          width={size}
          height={size}
          viewBox="0 0 50 50"
          className="spinner-svg"
        >
          <circle
            cx="25"
            cy="25"
            r="20"
            fill="none"
            stroke="rgba(255,255,255,0.08)"
            strokeWidth={ring}
          />
          <circle
            cx="25"
            cy="25"
            r="20"
            fill="none"
            stroke="rgba(154,92,255,0.9)"
            strokeLinecap="round"
            strokeWidth={ring}
            className="spinner-arc"
          />
        </svg>
      </div>
      <span className="spinner-label">{label}</span>
    </div>
  );
}

/* ─── Video fetch ────────────────────────────────────────── */
async function fetchVideos() {
  const [r1, r2] = await Promise.allSettled([
    safeGet("/public/videos", { params: { limit: 12 } }),
    safeGet("/videos/public", { params: { limit: 12 } }),
  ]);
  for (const r of [r1, r2]) {
    if (r.status === "fulfilled" && r.value.ok) {
      const items = normalizeItems(r.value.data);
      if (items.length) return items;
    }
  }
  return [];
}

/* ══════════════════════════════════════════════════════════
   ROOT
══════════════════════════════════════════════════════════ */
