/* ══════════════════════════════════════════════════════════
   3. LIVE SECTION
══════════════════════════════════════════════════════════ */
const _isAuthed = !!(
  (typeof localStorage !== "undefined" && localStorage.getItem("token")) ||
  (typeof sessionStorage !== "undefined" && sessionStorage.getItem("token"))
);

function LiveSection() {
  const [nextLiveAt, setNextLiveAt] = useState(null);
  const [segments, setSegments] = useState([]);
  const [showWatch, setShowWatch] = useState(false);
  const [liveOngoing, setLiveOngoing] = useState(false);
  const [loadingLive, setLoadingLive] = useState(true);

  const nextLiveAtRef = useRef(null);
  const liveOngoingRef = useRef(false);

  useEffect(() => {
    nextLiveAtRef.current = nextLiveAt;
  }, [nextLiveAt]);
  useEffect(() => {
    liveOngoingRef.current = liveOngoing;
  }, [liveOngoing]);

  function safeDate(v) {
    if (!v) return null;
    const d = new Date(v);
    if (!Number.isNaN(d.getTime())) return d;
    if (typeof v === "string") {
      const d2 = new Date(v.replace(" ", "T"));
      if (!Number.isNaN(d2.getTime())) return d2;
    }
    return null;
  }

  useEffect(() => {
    let cancelled = false;
    const ctrl = new AbortController();

    function setLiveState(next) {
      if (cancelled) return;
      setLiveOngoing((p) => (p === next ? p : next));
      liveOngoingRef.current = next;
    }
    function setNextLiveDate(d) {
      if (cancelled || !d) return;
      setNextLiveAt((p) => (p && p.getTime() === d.getTime() ? p : d));
      nextLiveAtRef.current = d;
    }

    async function fetchNextLive() {
      if (document.hidden) return;
      try {
        const res = await api.get(`/streamcontrol/${CHANNEL_ID}/next-live`, {
          params: { _: Date.now() },
          signal: ctrl.signal,
        });
        const data = res.data || {};
        const state = String(data.state || "").toLowerCase();
        if (state === "live_window" || data.is_live === true) {
          setLiveState(true);
          return;
        }
        const ts =
          data.next_live_datetime ||
          data.next_live_at ||
          data.next_event?.start_at ||
          data.event?.start_at ||
          null;
        const d = safeDate(ts) || parseNextLiveToLocalDate(ts);
        if (d) {
          setLiveState(false);
          setNextLiveDate(d);
        }
      } catch (e) {
        if (
          ctrl.signal.aborted ||
          String(e?.message || "").includes("ERR_NETWORK_IO_SUSPENDED")
        )
          return;
      }
    }

    async function fetchFallback() {
      if (!_isAuthed || document.hidden) return;
      try {
        const from = new Date();
        const to = new Date();
        to.setDate(to.getDate() + 60);
        const p2 = (n) => String(n).padStart(2, "0");
        const ymd = (d) => {
          const x = new Date(d);
          return `${x.getFullYear()}-${p2(x.getMonth() + 1)}-${p2(x.getDate())}`;
        };
        const res = await api.get("/admin/calendar/events", {
          params: { from: ymd(from), to: ymd(to), _: Date.now() },
          signal: ctrl.signal,
        });
        const items = Array.isArray(res.data?.events)
          ? res.data.events
          : Array.isArray(res.data)
            ? res.data
            : [];
        const now = Date.now();
        const liveEvents = items
          .filter((e) => String(e.type || "").toLowerCase() === "live")
          .map((e) => ({
            ...e,
            _start: safeDate(e.start_at),
            _end: e.end_at ? safeDate(e.end_at) : null,
          }))
          .filter((e) => e._start)
          .sort((a, b) => a._start - b._start);
        const current = liveEvents.find(
          (e) => e._start <= now && e._end && e._end >= now,
        );
        if (current) {
          setLiveState(true);
          return;
        }
        const upcoming = liveEvents.find((e) => e._start > now);
        if (upcoming) {
          setLiveState(false);
          setNextLiveDate(upcoming._start);
        }
      } catch (e) {
        if (ctrl.signal.aborted) return;
      }
    }

    async function refresh() {
      if (!liveOngoingRef.current && !nextLiveAtRef.current)
        setLoadingLive(true);
      await fetchNextLive();
      if (!cancelled && !liveOngoingRef.current && !nextLiveAtRef.current)
        await fetchFallback();
      if (!cancelled) setLoadingLive(false);
    }

    refresh();
    const intv = setInterval(refresh, 30_000);
    const onVis = () => {
      if (!document.hidden) refresh();
    };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      cancelled = true;
      ctrl.abort();
      clearInterval(intv);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, []);

  useEffect(() => {
    if (liveOngoing) {
      setSegments([]);
      setShowWatch(true);
      return;
    }
    if (!nextLiveAt) {
      setSegments([]);
      setShowWatch(false);
      return;
    }
    let cancelled = false;
    const labels = ["Days", "Hrs", "Min", "Sec"];
    const tick = () => {
      if (cancelled) return;
      const diffSec = (nextLiveAt - new Date()) / 1000;
      if (diffSec <= 0) {
        setSegments([]);
        setShowWatch(true);
        setLiveOngoing(true);
        return;
      }
      const s = Math.max(0, Math.floor(diffSec));
      const pad = (n) => String(n).padStart(2, "0");
      setSegments([
        { val: pad(Math.floor(s / 86400)), lbl: labels[0] },
        { val: pad(Math.floor((s % 86400) / 3600)), lbl: labels[1] },
        { val: pad(Math.floor((s % 3600) / 60)), lbl: labels[2] },
        { val: pad(s % 60), lbl: labels[3] },
      ]);
      setShowWatch(false);
    };
    tick();
    const intv = setInterval(tick, 1000);
    return () => {
      cancelled = true;
      clearInterval(intv);
    };
  }, [nextLiveAt, liveOngoing]);

  return (
    <section className="live">
      <div className="live__bg">
        <img
          src="/media/featured-bg.jpg"
          alt=""
          className="live__bg-img"
          loading="lazy"
          decoding="async"
        />
        <div className="live__bg-overlay" />
      </div>

      <div className="live__inner">
        <div className="live__info">
          {liveOngoing ? (
            <span className="live__pill live__pill--on">
              <span className="live__dot" />
              LIVE NOW
            </span>
          ) : (
            <span className="live__pill live__pill--off">UPCOMING</span>
          )}

          <h2 className="live__title">Live Stream</h2>

          <p className="live__desc">
            {liveOngoing
              ? "We are live! Join us now for real-time revelation and prophetic impartation."
              : segments.length
                ? "Tune in for our next live broadcast. Experience breakthrough teaching delivered live."
                : loadingLive
                  ? ""
                  : "Check back soon for our next live broadcast."}
          </p>

          {loadingLive && !liveOngoing && !segments.length && (
            <CircularSpinner label="Checking live schedule…" />
          )}

          {showWatch && (
            <Link to="/live-streaming" className="btn btn--live btn--lg">
              <span className="live__dot" />
              Watch Live
            </Link>
          )}
        </div>

        {segments.length > 0 && !liveOngoing && (
          <div className="live__countdown">
            <p className="live__cd-label">Next Broadcast Starts In</p>
            <div className="live__cd-row">
              {segments.map((seg, i) => (
                <React.Fragment key={seg.lbl}>
                  <div className="live__cd-block">
                    <span className="live__cd-num">{seg.val}</span>
                    <span className="live__cd-unit">{seg.lbl}</span>
                  </div>
                  {i < segments.length - 1 && (
                    <span className="live__cd-colon">:</span>
                  )}
                </React.Fragment>
              ))}
            </div>
          </div>
        )}
      </div>
    </section>
  );
}

/* ══════════════════════════════════════════════════════════
   4. LATEST TEACHING
══════════════════════════════════════════════════════════ */
function LatestTeaching() {
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);

  const getPublishTime = useCallback((v) => {
    const raw =
      v?.published_at ||
      v?.publish_date ||
      v?.publishedAt ||
      v?.publishedAtUtc ||
      v?.publish_at ||
      v?.created_at ||
      v?.createdAt ||
      v?.updated_at ||
      v?.updatedAt ||
      v?.metadata?.published_at ||
      v?.metadata?.publish_date ||
      v?.metadata?.publishedAt ||
      null;
    if (!raw) return 0;
    const d = new Date(raw);
    if (!Number.isNaN(d.getTime())) return d.getTime();
    if (typeof raw === "string") {
      const d2 = new Date(raw.replace(" ", "T"));
      if (!Number.isNaN(d2.getTime())) return d2.getTime();
    }
    return 0;
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      try {
        const items = await fetchVideos();
        const sorted = items
          .slice()
          .sort((a, b) => getPublishTime(b) - getPublishTime(a))
          .slice(0, 4);
        if (!cancelled) setVideos(sorted);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [getPublishTime]);

  return (
    <section className="teachings">
      <div className="teachings__head">
        <div>
          <p className="section-eyebrow">On Demand</p>
          <h2 className="section-title">Latest Teachings</h2>
          <p className="section-sub">
            A fresh impartation to strengthen your walk.
          </p>
        </div>
        <Link to="/catalog" className="btn btn--ghost btn--sm">
          Browse All
          <svg
            width="13"
            height="13"
            viewBox="0 0 13 13"
            fill="none"
            aria-hidden="true"
          >
            <path
              d="M1 6.5h11M7 1.5l5 5-5 5"
              stroke="currentColor"
              strokeWidth="1.6"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </Link>
      </div>

      {loading ? (
        <div className="teachings__state">
          <CircularSpinner label="Loading teachings…" />
        </div>
      ) : !videos.length ? (
        <div className="teachings__state">No videos found yet.</div>
      ) : (
        <div className="teachings__grid">
          {videos.map((v, idx) => {
            const rawThumb =
              v.thumbnail_url ||
              v?.metadata?.thumbnail_vertical_url ||
              v?.metadata?.thumbnail_url ||
              null;
            const thumb = absUrl(rawThumb) || DefaultThumb;
            const isDef = !absUrl(rawThumb);
            return (
              <Link key={v.id} to={`/watch/${v.id}`} className="vcard">
                <div
                  className={`vcard__thumb${isDef ? " vcard__thumb--default" : ""}`}
                >
                  <img
                    src={thumb}
                    alt={v.title || "Video"}
                    loading="lazy"
                    decoding="async"
                    onError={(e) => {
                      e.currentTarget.onerror = null;
                      e.currentTarget.src = DefaultThumb;
                    }}
                  />
                  <div className="vcard__play" aria-hidden="true">
                    <svg
                      viewBox="0 0 24 24"
                      fill="currentColor"
                      width="20"
                      height="20"
                    >
                      <path d="M5 3.5a.5.5 0 0 1 .765-.424l14 8a.5.5 0 0 1 0 .848l-14 8A.5.5 0 0 1 5 19.5z" />
                    </svg>
                  </div>
                </div>
                <div className="vcard__meta">
                  <h4 className="vcard__title">{v.title}</h4>
                  <p className="vcard__cat">
                    {v.category_name || v?.category?.name || ""}
                  </p>
                </div>
              </Link>
            );
          })}
        </div>
      )}
    </section>
  );
}

